@@ -1,12 +1,28 @@
 import { Router } from 'express';
+import { z } from 'zod';
 import { enqueueImport } from '../jobs/import.js';

+/** Contract for the untrusted import request body: unknown keys rejected,
+ *  every field bounded. Anything else is a 400, never enqueued. */
+const ImportRequestSchema = z
+  .object({
+    sourceUrl: z.string().url().max(2048),
+    format: z.enum(['csv', 'jsonl']),
+    rowLimit: z.number().int().min(1).max(100_000),
+  })
+  .strict();
+
 export const importRouter = Router();

 importRouter.post('/import', async (req, res) => {
-  await enqueueImport(req.body);
-  res.status(202).json({ queued: true });
+  const parsed = ImportRequestSchema.safeParse(req.body);
+  if (!parsed.success) {
+    res.status(400).json({ error: 'invalid import request' });
+    return;
+  }
+  await enqueueImport(parsed.data);
+  res.status(202).json({ queued: true });
 });
